from os import writefrom fastapi import (    APIRouter, FastAPI, HTTPException,)from config import settingsfrom pathlib import Pathimport jsonfrom pydantic import BaseModel, Field #1from typing import List, Dict  #1from fastapi import Query, UploadFile, Request #2from typing import Annotated, Literal #2from fastapi.responses import HTMLResponseimport osfrom fastapi.staticfiles import StaticFilesrouter = APIRouter(    tags=["test"],    prefix=settings.url.test,)app=FastAPI()items_storage: List[Dict] = []JSON_FILE = Path("items_data.json")def load_items() -> List[Dict]:    if JSON_FILE.exists():        with open(JSON_FILE, 'r', encoding='utf-8') as f:            return json.load(f)    return []def save_items(items: List[Dict]):    with open(JSON_FILE, 'w', encoding='utf-8') as f:        json.dump(items, f, ensure_ascii=False, indent=4)def get_next_id(items: List[Dict]) -> int:    if not items:        return 1    return max(item.get("id", 0) for item in items) + 1#1================next_id = 1class Item(BaseModel):    name: str    description: str | None = None    price: int    tax: int | None = None@router.post("/items/create", summary="первое задание")async def create_item(item:Item):    items = load_items()    item_data = {        "id": get_next_id(items),        "name": item.name,        "description": item.description,        "price": item.price,        "tax": item.tax,    }    items.append(item_data)    save_items(items)    return {        "user_info": item_data,        "message": "Товар успешно создан",        "total_items": len(items)    }#2===============@router.get("/items2/", summary="второе") #в ссылку вставляем ?q=ывафыasync def read_items(q: Annotated[str | None, Query(max_length=50)] = None):    items = load_items()    results = {"items": [{"item_id": "Foo"}, {"item_id": "Bar"}]}    for i in range(len(items)):        if items[i].get("name") == q:            results.update({"item_name": items[i].get("name")})            results.update({"item_id": items[i].get("id")})    if q:        results.update({"q": q})        return results#3================@router.get("/items3/{item_id}" , summary= "третье задание")async def read_items_by_id(    item_id: Annotated[int, Path(title="The ID of the item to get")]):    items = load_items()    for item in items:        if item["id"] == item_id:            return {                "item": item,                "message": f"Товар {item_id} найден"            }#4==============class ItemQuery(BaseModel):    name: str = Field("", max_length=100)    min_price: int = Field(0, ge=0, le=100)    max_price: int = Field(10, ge=0, le=10000000000)@router.get("/items4/", summary="четыре")async def get_items(filters: Annotated[ItemQuery, Query()]):    items = load_items()    for item in items:        if filters.name == item.get("name"):            return {"found_item": item}    return {"message": "Товар не найден", "search_name": filters.name}#============data_for_choose_format = {    "name": "kolobok",    "age": 0,    "killed by": "fox"}@router.get("/chooseformat/", summary = "тут надо выбрать json or html")async def choose_format(q: Annotated[Literal["json", "html"] | None, Query()] = None):    if q == "json":        return data_for_choose_format    elif q == "html":        html_content = f"""        <div class="user-card">                <h1>Досье</h1>                <p><strong>Имя:</strong> {data_for_choose_format['name']}</p>                <p><strong>Возраст:</strong> {data_for_choose_format['age']}</p>                <p><strong>кто убил:</strong> {data_for_choose_format['killed by']}</p>                <div>        """        return HTMLResponse(content=html_content)#============UPLOAD_DIRECTORY = "./static/uploads"ALLOWED_EXTENSIONS = {".png", ".jpg", ".jpeg", ".webp"}@router.post("/uploadfile/", summary= "загрузка фотке")async def create_upload_file(file: UploadFile, request: Request):    os.makedirs(UPLOAD_DIRECTORY, exist_ok=True)  #сделать папко если нема    image_files = ["image/png", "image/jpeg", "image/webp", "image/jpg"]    if file.content_type not in image_files:        raise HTTPException(            status_code=400,            detail=f"файл не поддерживается"        )    file_location = os.path.join(UPLOAD_DIRECTORY, file.filename)    with open(file_location, 'wb') as buffer:        content = await file.read()        buffer.write(content)    file_url = str(request.base_url) + f"static/uploads/{file.filename}"    return {"filename": file.filename,"url":file_url, "message": "Файл успешно сохранен"}